// spec: .qa/e2e/specs/guided-prayer.md (8.13)
// seed: tests/seed.admin.spec.ts + tests/seed.user1.spec.ts (две роли — asUser)
// ПРОД: только чтение. В админке ничего не нажимать, кроме открытия карточки молитвы.
import { test, expect } from '../../fixtures';
import { APPROVED_LINE, openFragment, saveProgress, restoreProgress } from '../_helpers/prayer-nav';

test.describe('Молитва по шагам', () => {
  test('GP-07 Имя и дата утверждения у пользователя совпадают с админкой (ערבית אשכנז «המעריב ערבים») #a5decf4a @prod-safe @mobile', async ({ asUser }) => {
    // 1. admin: /admin → «ערבית · נוסח אשכנז» → статус «המעריב ערבים»: «מאושר · <имя>, <дата>, <время>».
    const admin = await asUser('admin');
    await admin.goto('/admin');
    await expect(admin.getByText('ניהול תכני תפילה')).toBeVisible({ timeout: 20_000 });
    await admin.getByText(/^ערבית\s*.\s*נוסח אשכנז$/).first().click();
    await expect(admin.getByText('היסטוריית אישורים', { exact: true })).toBeVisible({ timeout: 20_000 });
    let adminMatch: RegExpMatchArray | null = null;
    await expect
      .poll(async () => {
        adminMatch = (await admin.locator('body').innerText()).match(/המעריב ערבים[\s\S]{0,60}?מאושר\s*.\s*([^\n,]+?),\s*(\d{1,2}\.\d{1,2}\.\d{4})/);
        return adminMatch !== null;
      })
      .toBe(true);
    const [, approver, date] = adminMatch as unknown as RegExpMatchArray;

    // 2. user1: /prayer/arvit_ashkenaz → «3 מתוך 15» → строка «מקור: … · אושר על ידי …».
    const user = await asUser('user1');
    const saved = await saveProgress(user);
    try {
      await openFragment(user, 'arvit_ashkenaz', 3);
      const line = user.getByText(APPROVED_LINE);
      await expect(line).toBeVisible();
      await expect(line).toContainText(`אושר על ידי ${approver.trim()}, ${date}`);
    } finally {
      // 3. Уборка: вернуть prayer-progress у user1.
      await restoreProgress(user, saved);
    }
  });
});
